import React, { useEffect, useState } from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import axios from "axios";
import "../styles/main.css";

export default function AdminManageHome() {
  const [data, setData] = useState({
    bannerVideos: [],
    welcomeText: "",
    activityImages: [],
    threeCol: [],
    testimonials: [],
  });
  const [selectedVideoFile, setSelectedVideoFile] = useState(null);
  const [loading, setLoading] = useState(false);

  // Fetch current home content
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => {
        setData({
          bannerVideos: res.data.bannerVideos || [],
          welcomeText: res.data.welcomeText || "",
          activityImages: res.data.activityImages || [],
          threeCol: res.data.threeCol || [],
          testimonials: res.data.testimonials || [],
        });
      })
      .catch((err) => console.error("Error loading home data:", err));
  }, []);

  // Handle file uploads
  const handleFileUpload = async (e, key) => {
    const files = e.target.files;
    if (!files.length) return;
    const formData = new FormData();
    for (let f of files) formData.append("files", f);

    try {
      const res = await axios.post("http://localhost:5000/api/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setData((prev) => ({
        ...prev,
        [key]: [...prev[key], ...res.data.urls],
      }));
    } catch (err) {
      console.error("Upload failed:", err);
      alert("Upload failed. Please try again.");
    }
  };

  // Delete item from array
  const handleDelete = (key, index) => {
    setData((prev) => ({
      ...prev,
      [key]: prev[key].filter((_, i) => i !== index),
    }));
  };

  // Add 3-column section card
  const addThreeCol = () => {
    setData((prev) => ({
      ...prev,
      threeCol: [...prev.threeCol, { title: "New Section", text: "" }],
    }));
  };

  const handleThreeColChange = (index, field, value) => {
    const updated = [...data.threeCol];
    updated[index][field] = value;
    setData({ ...data, threeCol: updated });
  };

  // Save all data
//   const handleSave = async () => {
//     setLoading(true);
//     try {
//       //   await axios.post("http://localhost:5000/api/admin/home", data);
//       const token = localStorage.getItem("token");

//       await axios.post(
//         "http://localhost:5000/api/home",
//         data,
//         {
//             headers: {
//                 "Content-Type": "application/json",
//                 Authorization: `Bearer ${token}`, // ✅ added
//             },
//         }
//       );

//       alert("✅ Home Page content saved successfully!");
//     } catch (err) {
//       console.error("Save failed:", err);
//       alert("❌ Failed to save. Try again.");
//     } finally {
//       setLoading(false);
//     }
//   };
    const handleSave = async () => {
        try {
            let videoUrls = data.bannerVideos || [];

            if (selectedVideoFile) {
                const uploadedUrl = await handleVideoUpload(selectedVideoFile);
                if (uploadedUrl) videoUrls = [uploadedUrl];
            }

            await axios.post("http://localhost:5000/api/admin/home", {
                welcomeText: data.welcomeText,
                bannerVideos: videoUrls,
                activities: data.activities || [],
                testimonialVideos: data.testimonialVideos || [],
            });

            alert("✅ Changes saved successfully!");
        } catch (err) {
           console.error("Save failed:", err);
           alert("Save failed. Check console for details.");
        }
    };



  const handleVideoUpload = async (file) => {
    const formData = new FormData();
    formData.append("file", file);

    try {
        const res = await axios.post("http://localhost:5000/api/upload", formData, {
            headers: { "Content-Type": "multipart/form-data" },
        });
        return res.data.url; // Full URL of uploaded video
    } catch (err) {
      console.error("Upload failed:", err);
      alert("Video upload failed");
      return null;
    }
  };


  return (
    <div className="admin-manage-home">
      <h1 className="page-title">🏠 Manage Home Page</h1>

      {/* --- Banner Videos --- */}
      <section className="admin-section">
        <div className="section-header">
          <h2>🎥 Banner Videos</h2>
          <input
            type="file"
            accept="video/*"
            multiple
            onChange={(e) => handleFileUpload(e, "bannerVideos")}
          />
        </div>
        <div className="video-preview-grid">
          {data.bannerVideos?.length > 0 ? (
            data.bannerVideos.map((vid, i) => (
              <div key={i} className="media-card">
                <video src={vid} controls />
                <button onClick={() => handleDelete("bannerVideos", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No videos added yet</p>
          )}
        </div>
      </section>

      {/* --- Welcome Text --- */}
      <section className="admin-section">
        <h2>👋 Welcome Text</h2>
        <ReactQuill
          theme="snow"
          value={data.welcomeText}
          onChange={(val) => setData({ ...data, welcomeText: val })}
        />
      </section>

      {/* --- Activity Images --- */}
      <section className="admin-section">
        <div className="section-header">
          <h2>🏫 Activity Images</h2>
          <input
            type="file"
            accept="image/*"
            multiple
            onChange={(e) => handleFileUpload(e, "activityImages")}
          />
        </div>
        <div className="image-grid">
          {data.activityImages?.length > 0 ? (
            data.activityImages.map((img, i) => (
              <div key={i} className="media-card">
                <img src={img} alt="activity" />
                <button onClick={() => handleDelete("activityImages", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No activity images added yet</p>
          )}
        </div>
      </section>

      {/* --- Three Column --- */}
      <section className="admin-section">
        <div className="section-header">
          <h2>📰 3-Column Section</h2>
          <button onClick={addThreeCol} className="btn-add">➕ Add</button>
        </div>
        <div className="three-col-preview">
          {data.threeCol?.length > 0 ? (
            data.threeCol.map((col, i) => (
              <div key={i} className="three-col-card">
                <input
                  type="text"
                  value={col.title}
                  onChange={(e) => handleThreeColChange(i, "title", e.target.value)}
                  placeholder="Title"
                />
                <textarea
                  value={col.text}
                  onChange={(e) => handleThreeColChange(i, "text", e.target.value)}
                  placeholder="Description"
                />
                <button onClick={() => handleDelete("threeCol", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No 3-column items yet</p>
          )}
        </div>
      </section>

      {/* --- Testimonials --- */}
      <section className="admin-section">
        <div className="section-header">
          <h2>💬 Testimonial Videos</h2>
          <input
            type="file"
            accept="video/*"
            multiple
            onChange={(e) => handleFileUpload(e, "testimonials")}
          />
        </div>
        <div className="video-preview-grid">
          {data.testimonials?.length > 0 ? (
            data.testimonials.map((vid, i) => (
              <div key={i} className="media-card">
                <video src={vid} controls />
                <button onClick={() => handleDelete("testimonials", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No testimonials yet</p>
          )}
        </div>
      </section>

      {/* --- Save Button --- */}
      <div className="save-wrapper">
        <button onClick={handleSave} disabled={loading} className="save-btn">
          {loading ? "Saving..." : "💾 Save Changes"}
        </button>
      </div>
    </div>
  );
}
